push.css:
.fxs .push.gr{background:none;box-shadow:0 26px 30px rgba(0,0,0,.42)}
.fxs .gr .turf{position:absolute;left:-16px;top:-22px;width:232px;height:150px;pointer-events:none}
.fxs .gr .turf svg{display:block;width:232px;height:150px;overflow:visible}
.fxs .push.gr span{color:#FFFFF4;text-shadow:0 3px 0 #2A6410,1.5px 0 0 #2A6410,-1.5px 0 0 #2A6410,0 -1.5px 0 #2A6410,0 0 14px rgba(255,255,230,.55)}
.fxs .push.gr::after{border-color:rgba(205,245,150,.95)}
.fxs .gr .gs1,.fxs .gr .gs2{transform-box:view-box;transform-origin:0 0;animation:fxgrSway 2.4s ease-in-out infinite}
.fxs .gr .gs2{animation-delay:-1.2s}
@keyframes fxgrSway{0%,100%{transform:skewX(-10deg)}50%{transform:skewX(10deg)}}
.fxs .tap.gr{color:#E6FFC2}
.fxs .pressed.gr{background:none;box-shadow:none}
.fxs .clips{position:absolute;z-index:4;left:50%;top:calc(50% - 40px);width:0;height:0}
.fxs .clips i{position:absolute;opacity:0;animation:fxgrFly .95s cubic-bezier(.15,.7,.3,1) var(--d) both}
.fxs .clips .bl{left:-2px;top:-7px;width:4px;height:14px;border-radius:50% 50% 30% 30%/90% 90% 10% 10%;background:var(--c)}
.fxs .clips .pt{left:-4px;top:-4px;width:8px;height:8px;border-radius:50% 50% 50% 0;background:var(--c)}
@keyframes fxgrFly{0%{opacity:0;transform:translate(0,0) rotate(0) scale(.5)}10%{opacity:1}62%{opacity:1;transform:translate(var(--x),var(--y)) rotate(var(--r)) scale(1)}
  100%{opacity:0;transform:translate(var(--x),calc(var(--y) + 50px)) rotate(calc(var(--r) * 1.5)) scale(.9)}}
@media (prefers-reduced-motion:reduce){.fxs .gr .gs1,.fxs .gr .gs2{animation:none}
.fxs .clips{display:none}}
/* 設定の「演出を控えめにする」＝視差効果を減らすと同じ形（16.6） */
.fxs.calm .gr .gs1,.fxs.calm .gr .gs2{animation:none}
.fxs.calm .clips{display:none}

board.css:
.fxs .rb.t-ranch{--hdB:0 solid transparent;--cardO:0 solid transparent;--zBg:#F7FBEF;--zB:1.5px solid #DDEDC0;--sep:2px dotted #CFE6A8;--rs:14px;--nR:8px;--w2B:0 solid transparent;--tagBg:#F7FBEF;--tagInk:#3D5A1E;--tagLine:#CFE6A8;--bg:#F3F8E6;--ink:#2B3A18;--sub:#5A6A42;--card:#FFFFFF;--cardB:2px solid #CFE6A8;--cardS:0 3px 0 #DCEBC0;--radius:18px;--font:"Zen Maru Gothic";--dfont:"Zen Maru Gothic";--dw:900;--logo:#24470C;--logoS:0 2px 0 rgba(255,255,255,.55);--hd:linear-gradient(180deg,#A9DA5E,#86C23C);--hdInk:#24470C;--acc:#2F6A12;--h1:#2B3A18;--coin:#FFD84A;--coinInk:#5A3A1A;--rbFace:#FFFFFF}
.fxs .rb.t-ranch .hd{border-bottom:4px solid #A8743F}
.fxs .rb.t-ranch{background-image:radial-gradient(#E1EFC4 1.6px,transparent 2px);background-size:18px 18px}
/* 設定の「演出を控えめにする」＝視差効果を減らすと同じ形（16.6） */
